const original = $('04 - Build Saudi Research Prompt').item.json;
const httpResponse = $json;

let aiText = '';
try {
  aiText = (httpResponse.choices && httpResponse.choices[0] && httpResponse.choices[0].message && httpResponse.choices[0].message.content) || '';
} catch (e) {
  aiText = '';
}

function tryParse(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    return null;
  }
}

let cleaned = (aiText || '').trim();
let parsed = tryParse(cleaned);

if (!parsed) {
  let fenceStripped = cleaned;
  if (fenceStripped.indexOf('```') !== -1) {
    fenceStripped = fenceStripped.replace(/```(json)?/gi, '').trim();
  }
  parsed = tryParse(fenceStripped);
  if (parsed) cleaned = fenceStripped;
}

if (!parsed) {
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    const candidate = cleaned.substring(firstBrace, lastBrace + 1);
    parsed = tryParse(candidate);
  }
}

if (!parsed || typeof parsed !== 'object') {
  return {
    json: {
      product_name: original.product_name,
      brand: original.brand,
      category: original.category,
      selling_price: original.selling_price,
      currency: original.currency,
      product_url: original.product_url,
      source: original.source,
      research_parse_error: true,
      research_status: 'FAILED',
      raw_ai_text: aiText
    }
  };
}

return {
  json: Object.assign({}, original, parsed, {
    research_parse_error: false,
    research_status: 'VALID'
  })
};

const item = $json;

if (item.research_parse_error === true || item.research_status === 'FAILED') {
  return {
    json: Object.assign({}, item, {
      verified_source_count: 0,
      saudi_source_count: 0,
      gcc_source_count: 0,
      global_source_count: 0,
      verified_price_count: 0,
      evidence_quality_score: 0,
      evidence_warning: ['PARSE_FAILED']
    })
  };
}

const sources = Array.isArray(item.evidence_sources) ? item.evidence_sources : [];

function hasUrl(s) {
  return s && typeof s.url === 'string' && s.url.trim().length > 0;
}

const verifiedSourceCount = sources.filter(hasUrl).length;

const saudiSources = sources.filter(function(s) {
  return hasUrl(s) && s.country_relevance === 'SAUDI' && s.verified_saudi_source === true;
});
const gccSources = sources.filter(function(s) {
  return hasUrl(s) && s.country_relevance === 'GCC';
});
const globalSources = sources.filter(function(s) {
  return hasUrl(s) && (s.country_relevance === 'GLOBAL' || s.country_relevance === 'OTHER');
});

const saudiSourceCount = saudiSources.length;
const gccSourceCount = gccSources.length;
const globalSourceCount = globalSources.length;

const observedPrices = Array.isArray(item.observed_prices) ? item.observed_prices : [];
const verifiedPrices = observedPrices.filter(function(p) {
  return p && p.verified === true && typeof p.price_sar === 'number' && p.price_sar > 0 && typeof p.source_url === 'string' && p.source_url.trim().length > 0;
});
const verifiedPriceCount = verifiedPrices.length;

const observedPriceRangeSar = verifiedPriceCount > 0 ? {
  min: Math.min.apply(null, verifiedPrices.map(function(p) { return p.price_sar; })),
  max: Math.max.apply(null, verifiedPrices.map(function(p) { return p.price_sar; }))
} : { min: null, max: null };

const warnings = [];

if (verifiedSourceCount === 0) {
  warnings.push('NO_SOURCES');
}
if (saudiSourceCount === 0) {
  warnings.push('NO_VERIFIED_SAUDI_SOURCES');
}
if (verifiedPriceCount === 0) {
  warnings.push('NO_VERIFIED_PRICES');
}

const marketPresence = Number(item.market_presence_score) || 0;
const demandEvidence = Number(item.demand_evidence_score) || 0;

if (marketPresence > 0 && demandEvidence === 0) {
  warnings.push('PRESENCE_WITHOUT_DEMAND_EVIDENCE');
}
if (demandEvidence >= 6 && saudiSourceCount === 0) {
  warnings.push('DEMAND_CLAIM_WITHOUT_SAUDI_SOURCE');
}

const confidence = Number(item.research_confidence_score) || 0;
if (confidence >= 50 && verifiedSourceCount === 0) {
  warnings.push('CONFIDENCE_NOT_SUPPORTED_BY_SOURCES');
}

function clamp(n, min, max) {
  const num = Number(n) || 0;
  return Math.min(max, Math.max(min, num));
}

const sourceTypeDiversity = new Set(sources.filter(hasUrl).map(function(s) { return s.source_type; })).size;

let evidenceQualityScore =
  clamp(saudiSourceCount * 2, 0, 6) +
  clamp(sourceTypeDiversity, 0, 2) +
  clamp(verifiedPriceCount, 0, 2);
evidenceQualityScore = clamp(evidenceQualityScore - warnings.length, 0, 10);

return {
  json: Object.assign({}, item, {
    verified_source_count: verifiedSourceCount,
    saudi_source_count: saudiSourceCount,
    gcc_source_count: gccSourceCount,
    global_source_count: globalSourceCount,
    verified_price_count: verifiedPriceCount,
    observed_price_range_sar: observedPriceRangeSar,
    evidence_quality_score: evidenceQualityScore,
    evidence_warning: warnings
  })
};

const item = $json;

if (item.research_parse_error === true || item.research_status === 'FAILED') {
  return {
    json: Object.assign({}, item, {
      research_status: 'FAILED',
      saudi_market_score: null
    })
  };
}

function clamp(n, min, max) {
  const num = Number(n) || 0;
  return Math.min(max, Math.max(min, num));
}

const verifiedSourceCount = Number(item.verified_source_count) || 0;

if (verifiedSourceCount === 0) {
  return {
    json: Object.assign({}, item, {
      research_status: 'INSUFFICIENT_EVIDENCE',
      saudi_market_score: null
    })
  };
}

const demandEvidence = clamp(item.demand_evidence_score, 0, 10);
const tiktok = clamp(item.tiktok_fit_score, 0, 10);
const snapchat = clamp(item.snapchat_fit_score, 0, 10);
const instagram = clamp(item.instagram_fit_score, 0, 10);
const platformFit = (tiktok + snapchat + instagram) / 3;

const competition = clamp(item.competition_score, 0, 10);
const competitionOpportunity = 10 - competition;

const saturation = clamp(item.saturation_risk_score, 0, 10);
const lowSaturationOpportunity = 10 - saturation;

const evidenceQuality = clamp(item.evidence_quality_score, 0, 10);

const researchConfidence = clamp((Number(item.research_confidence_score) || 0) / 10, 0, 10);

const weights = {
  demandEvidence: 0.30,
  platformFit: 0.20,
  competitionOpportunity: 0.15,
  lowSaturationOpportunity: 0.10,
  evidenceQuality: 0.15,
  researchConfidence: 0.10
};

const rawScore =
  (weights.demandEvidence * demandEvidence) +
  (weights.platformFit * platformFit) +
  (weights.competitionOpportunity * competitionOpportunity) +
  (weights.lowSaturationOpportunity * lowSaturationOpportunity) +
  (weights.evidenceQuality * evidenceQuality) +
  (weights.researchConfidence * researchConfidence);

const saudiMarketScore = clamp(rawScore * 10, 0, 100);

return {
  json: Object.assign({}, item, {
    saudi_market_score: Number(saudiMarketScore.toFixed(2)),
    research_status: 'VALID',
    saudi_market_score_breakdown: {
      demand_evidence: demandEvidence,
      market_presence_score: clamp(item.market_presence_score, 0, 10),
      platform_fit: Number(platformFit.toFixed(2)),
      competition_opportunity: competitionOpportunity,
      low_saturation_opportunity: lowSaturationOpportunity,
      evidence_quality: evidenceQuality,
      research_confidence: Number(researchConfidence.toFixed(2)),
      weights: weights
    }
  })
};

const config = $('00 - Research Config').first().json;
const topN = Number(config.top_n) || 3;

const allItems = $input.all().map(function(i) { return i.json; });

const validItems = allItems.filter(function(item) { return item.research_status === 'VALID'; });
const failedItems = allItems.filter(function(item) { return item.research_status !== 'VALID'; });

const sortedValid = validItems.slice().sort(function(a, b) {
  return (Number(b.saudi_market_score) || 0) - (Number(a.saudi_market_score) || 0);
});

const top = sortedValid.slice(0, topN).map(function(item, index) {
  return {
    rank: index + 1,
    product_name: item.product_name,
    research_status: item.research_status,
    saudi_market_score: item.saudi_market_score,
    market_presence_score: item.market_presence_score,
    demand_evidence_score: item.demand_evidence_score,
    competition_score: item.competition_score,
    saturation_risk_score: item.saturation_risk_score,
    recommended_platform: item.recommended_platform,
    tiktok_fit_score: item.tiktok_fit_score,
    snapchat_fit_score: item.snapchat_fit_score,
    instagram_fit_score: item.instagram_fit_score,
    observed_price_range_sar: item.observed_price_range_sar,
    verified_price_count: item.verified_price_count,
    selling_angles: item.selling_angles,
    risks: item.risks,
    verified_source_count: item.verified_source_count,
    saudi_source_count: item.saudi_source_count,
    gcc_source_count: item.gcc_source_count,
    global_source_count: item.global_source_count,
    research_confidence_score: item.research_confidence_score,
    evidence_sources: item.evidence_sources,
    evidence_warning: item.evidence_warning,
    research_parse_error: item.research_parse_error || false,
    summary: item.summary
  };
});

const summaryItem = {
  is_summary: true,
  valid_product_count: validItems.length,
  failed_product_count: failedItems.length,
  needs_more_candidates: validItems.length < topN,
  returned_count: top.length
};

return [{ json: summaryItem }].concat(top.map(function(item) { return { json: item }; }));
